$$
\begin{array}{l}
\quad \mathbf{w}\_{E,B}^{-u} - \mathbf{w}\_{E,B}  
ewline \approx 
\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{E,b}\mathbf{H}\_{E,b}) (\mathbf{w}\_{E-1,B}^{-u} - \mathbf{w}\_{E-1,B}) +
\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{E,b}\mathbf{H}\_{E,b}) rac{\eta\_{E,b(u)}}{|\mathcal{B}\_{E,b(u)}|} 
abla l(\mathbf{w}\_{E,b(u)};u) 
