ewline\quad+\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{E,b}\mathbf{H}\_{E,b})\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{E-1,b}\mathbf{H}\_{E-1,b}) rac{\eta\_{E-1,b(u)}}{|\mathcal{B}\_{E-1,b(u)}|} 
abla l(\mathbf{w}\_{E-1,b(u)};u)
ewline\quad+
\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{E,b}\mathbf{H}\_{E,b}) rac{\eta\_{E,b(u)}}{|\mathcal{B}\_{E,b(u)}|} 
abla l(\mathbf{w}\_{E,b(u)};u)\approx\cdots
ewline\approx\prod\_{e=E}^{1}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b}) (\mathbf{w}\_{0,B}^{-u} - \mathbf{w}\_{0,B})
ewline\quad+\prod\_{e=E}^{2}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{1,b}\mathbf{H}\_{1,b}) rac{\eta\_{1,b(u)}}{|\mathcal{B}\_{1,b(u)}|} 
abla l(\mathbf{w}\_{1,b(u)};u)
ewline\quad+\prod\_{e=E}^{3}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{2,b}\mathbf{H}\_{2,b}) rac{\eta\_{2,b(u)}}{|\mathcal{B}\_{2,b(u)}|} 
abla l(\mathbf{w}\_{2,b(u)};u)
ewline\quad+\cdots
ewline\quad+\prod\_{e=E}^{E}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{E-1,b}\mathbf{H}\_{E-1,b}) rac{\eta\_{E-1,b(u)}}{|\mathcal{B}\_{E-1,b(u)}|} 
abla l(\mathbf{w}\_{E-1,b(u)};u)
ewline\qquad\qquad\qquad\qquad\qquad\qquad\quad\;+
\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{E,b}\mathbf{H}\_{E,b}) rac{\eta\_{E,b(u)}}{|\mathcal{B}\_{E,b(u)}|} 
abla l(\mathbf{w}\_{E,b(u)};u)
ewline\approx\prod\_{e=E}^{0}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b}) (\mathbf{w}\_{0,0}^{-u} - \mathbf{w}\_{0,0})
ewline\quad+\prod\_{e=E}^{1}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{0,b}\mathbf{H}\_{0,b}) rac{\eta\_{0,b(u)}}{|\mathcal{B}\_{0,b(u)}|} 
abla l(\mathbf{w}\_{0,b(u)};u)
ewline\quad+\prod\_{e=E}^{2}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{1,b}\mathbf{H}\_{1,b}) rac{\eta\_{1,b(u)}}{|\mathcal{B}\_{1,b(u)}|} 
abla l(\mathbf{w}\_{1,b(u)};u)
ewline\quad+\prod\_{e=E}^{3}\prod\_{b=B-1}^{0}(\mathbf{I}-\eta\_{e,b}\mathbf{H}\_{e,b})\cdot\prod\_{b=B-1}^{b(u)+1}(\mathbf{I}-\eta\_{2,b}\mathbf{H}\_{2,b}) rac{\eta\_{2,b(u)}}{|\mathcal{B}\_{2,b(u)}|} 
